package com.hau.exam.infrastructure.external;
import com.hau.exam.application.port.out.QuestionCatalogPort;import com.hau.exam.domain.exception.DomainException;import com.hau.exam.domain.model.Difficulty;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.*;import tools.jackson.databind.*;
@Component public class QuestionServiceAdapter implements QuestionCatalogPort{
 private final RestClient client;private final ObjectMapper mapper;private final String base;
 public QuestionServiceAdapter(RestClient.Builder b,ObjectMapper m,@Value("${exam.question-service-url}")String u){client=b.build();mapper=m;base=u;}
 public List<QuestionCandidate>approvedQuestions(String faculty,UUID subject,UUID chapter,UUID topic,Difficulty difficulty,String token){try{String raw=client.get().uri(builder->{builder.path(base+"/api/v1/questions").queryParam("facultyId",faculty).queryParam("subjectId",subject).queryParam("chapterId",chapter).queryParamIfPresent("topicId",Optional.ofNullable(topic)).queryParam("difficulty",difficulty).queryParam("status","APPROVED").queryParam("page",0).queryParam("size",100);return builder.build();}).headers(h->h.setBearerAuth(token)).retrieve().body(String.class);JsonNode items=mapper.readTree(raw).at("/data/items");if(!items.isArray())throw new DomainException("Invalid Question Service response");List<QuestionCandidate>out=new ArrayList<>();for(JsonNode q:items)out.add(new QuestionCandidate(UUID.fromString(q.get("id").asText()),q.get("facultyId").asText(),UUID.fromString(q.get("subjectId").asText()),UUID.fromString(q.get("chapterId").asText()),q.get("topicId")==null||q.get("topicId").isNull()?null:UUID.fromString(q.get("topicId").asText()),Difficulty.valueOf(q.get("difficulty").asText()),q.get("status").asText()));return out;}catch(RestClientException e){throw new DomainException("Question Service unavailable");}catch(DomainException e){throw e;}catch(Exception e){throw new DomainException("Invalid Question Service response");}}
}
